using PcTidy.Core.Model;

namespace PcTidy.Catalog.Services;

/// <summary>
/// The service verdict table. Owned by the Services research pass (see the vault page "10 Research/Services").
/// Written in our own words. Sources are Microsoft or vendor support pages; entries without a source come from
/// general knowledge and say "unverified" in Why.
/// Notes for the scanner:
/// - Names ending in "_*" are per-user service templates. The instance (e.g. "CDPUserSvc_1a2b3c") is recreated at
///   every sign-in, so a change only sticks when it is made on the template key (the name without "_*").
/// - Anti-cheat names are exact here; the prefix patterns in SpeedProtectedNames (EasyAntiCheat*, FACEIT*, ...)
///   should still be checked, because some anti-cheat drivers use changing names.
/// - Protected and Harmful entries are never offered. If one is found Disabled (or Manual where Windows uses
///   Automatic), the bad-services repair may put it back to a Windows default.
/// </summary>
internal static class ServiceCatalogData
{
    private static IReadOnlyList<ServiceStart> D(params ServiceStart[] s) => s;
    private static readonly IReadOnlyList<string> None = Array.Empty<string>();

    private const ServiceStart A = ServiceStart.Automatic;
    private const ServiceStart AD = ServiceStart.AutomaticDelayed;
    private const ServiceStart M = ServiceStart.Manual;
    private const ServiceStart Off = ServiceStart.Disabled;
    private const ServiceStart Sys = ServiceStart.System;

    // Microsoft and vendor sources
    private const string MsIoT = "https://learn.microsoft.com/windows/iot/iot-enterprise/optimize/services";
    private const string MsServer = "https://learn.microsoft.com/windows-server/security/windows-services/security-guidelines-for-disabling-system-services-in-windows-server";
    private const string MsPerUser = "https://learn.microsoft.com/windows/application-management/per-user-services-in-windows";
    private const string MsPrintNightmare = "https://msrc.microsoft.com/update-guide/vulnerability/CVE-2021-34527";
    private const string MsGamingServices = "https://support.microsoft.com/help/5004327";
    private const string MsOutlookSearch = "https://learn.microsoft.com/outlook/troubleshoot/user-interface/windows-search-service-setting-results-in-no-matches-found";
    private const string MsTextInput = "https://learn.microsoft.com/answers/questions/1664173/would-disabling-text-input-management-service-woul";
    private const string FaceitSupport = "https://support.faceit.com/hc/en-us/articles/360014177880-The-service-cannot-be-started";
    private const string SysMainBench = "https://www.windowslatest.com/2026/10/26/everyone-says-disabling-sysmain-speeds-up-windows-11-so-i-benchmarked-it-on-two-pcs-k4l9/";

    private static ServiceEntry Prot(string name, string what, IReadOnlyList<ServiceStart> defaults, string why, string? breaks = null, string? source = null, bool w11 = false)
        => new(name, what, ServiceVerdict.Protected, defaults, null, None, why, breaks, source, w11);

    private static ServiceEntry Harm(string name, string what, IReadOnlyList<ServiceStart> defaults, string why, string breaks, string? source = null, bool w11 = false)
        => new(name, what, ServiceVerdict.Harmful, defaults, null, None, why, breaks, source, w11);

    private static ServiceEntry Plac(string name, string what, IReadOnlyList<ServiceStart> defaults, string why, string? breaks = null, string? source = null, bool w11 = false)
        => new(name, what, ServiceVerdict.Placebo, defaults, null, None, why, breaks, source, w11);

    private static ServiceEntry Sit(string name, string what, IReadOnlyList<ServiceStart> defaults, ServiceStart? recommended, string why, string breaks, string? source = null, bool w11 = false)
        => new(name, what, ServiceVerdict.Situational, defaults, recommended, None, why, breaks, source, w11);

